<?php $selected=array_map('strval',(array)($f['axis']['collection']??[]));$topics=[];foreach($catalogFilters['axes'] as $a)if($a['axis_key']==='collection')$topics=$a['options']; ?>
<fieldset><legend>دسته‌بندی موضوعی</legend><?php foreach($topics as $row): ?><label class="check"><input type="checkbox" name="axis[collection][]" value="<?= (int)$row['id'] ?>" <?= in_array((string)$row['id'],$selected,true)?'checked':'' ?>><?= e($row['title']) ?></label><?php endforeach ?><?php if(!$topics): ?><p>موضوعی با داده منتشرشده وجود ندارد.</p><?php endif ?></fieldset>
<div class="fields"><?php foreach(['country'=>'کشور','province'=>'استان','county'=>'شهرستان','city'=>'شهر'] as $level=>$title): ?><label><?= e($title.' محل تولد') ?><select name="geo_<?= $level ?>"><option value="">همه</option><?php foreach($catalogFilters['geo'][$level] as $row): ?><option value="<?= (int)$row['id'] ?>" <?= (string)($f['geo_'.$level]??'')===(string)$row['id']?'selected':'' ?>><?= e($row['title']) ?></option><?php endforeach ?></select></label><?php endforeach ?></div>
